// Lê o aviso do PagBank. Só guarda quando o status é PAGO.
const b = $json.body || {};
const ch = (Array.isArray(b.charges) && b.charges[0]) || b;
const status = String(ch.status || b.status || '').toUpperCase();
if (status !== 'PAID') return [];
const ref = String(b.reference_id || ch.reference_id || ch.id || '').replace(/[^A-Za-z0-9_-]/g, '').slice(0, 60);
if (!ref) return [];
const centavos = Number((ch.amount && (ch.amount.value ?? ch.amount.summary?.paid)) ?? (b.amount && b.amount.value) ?? 0);
const tipo = String((ch.payment_method && ch.payment_method.type) || '').toUpperCase();
const cli = b.customer || {};
const ph = (cli.phones && cli.phones[0]) || {};
const telefone = ((ph.area || '') + (ph.number || '')).replace(/\D/g, '');
const m = ref.match(/^curso-(\d+)-/);
const sd = $getWorkflowStaticData('global');
sd.vendas = sd.vendas || {};
const jaTinha = !!sd.vendas[ref];
sd.vendas[ref] = { ref, nome: cli.name || '', email: cli.email || '', telefone: telefone ? ('55' + telefone.replace(/^55/, '')) : '', forma: tipo === 'PIX' ? 'pix' : 'cartao', valor: centavos / 100, pagoEm: Date.now(), convId: m ? m[1] : '', src: 'pagbank' };
const ks = Object.keys(sd.vendas);
if (ks.length > 300) ks.sort((a, b) => sd.vendas[a].pagoEm - sd.vendas[b].pagoEm).slice(0, ks.length - 300).forEach(k => delete sd.vendas[k]);
if (jaTinha) return [];   // aviso repetido do banco: não avisa de novo
return [{ json: sd.vendas[ref] }];

const CHAVE = 'yWlRpqQLl377t9C7_qU'; // chave secreta: a mesma que você cola no painel do gestor (aba Vendas)
// Registra uma venda enviada por outro fluxo (ex.: o atendimento). Corpo: { chave, nome, email, telefone, forma, valor, ref, convId }
const b = $json.body || {};
if (b.chave !== CHAVE) return [{ json: { ok: false, err: 'chave' } }];
const ref = String(b.ref || ('man' + Date.now().toString(36))).replace(/[^A-Za-z0-9_-]/g, '').slice(0, 60);
const sd = $getWorkflowStaticData('global');
sd.vendas = sd.vendas || {};
sd.vendas[ref] = { ref, nome: String(b.nome || ''), email: String(b.email || ''), telefone: String(b.telefone || '').replace(/[^\d]/g, ''), forma: /pix/i.test(b.forma || '') ? 'pix' : 'cartao', valor: Number(b.valor) || 0, pagoEm: Date.now(), convId: b.convId || '', src: 'manual' };
return [{ json: { ok: true, ref } }];

const CHAVE = 'yWlRpqQLl377t9C7_qU'; // chave secreta: a mesma que você cola no painel do gestor (aba Vendas)
// Entrega a lista de vendas pagas ao painel do gestor (só com a chave certa)
const q = $json.query || {};
if (q.chave !== CHAVE) return [{ json: { ok: false, err: 'chave', vendas: [] } }];
const sd = $getWorkflowStaticData('global');
const v = Object.values(sd.vendas || {}).sort((a, b) => b.pagoEm - a.pagoEm).slice(0, 100);
return [{ json: { ok: true, vendas: v } }];
